export function makeElement(tag,className='',text){const node=document.createElement(tag);node.className=className;if(text!==undefined)node.textContent=text;return node;}
export function svgElement(tag,attrs={}){const node=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const[key,value]of Object.entries(attrs))node.setAttribute(key,String(value));return node;}
export function barChart(days,{maxHeight=140,unit='мин'}={}){const chart=makeElement('div','activity-chart');const max=Math.max(60,...days.map(d=>d.value));chart.setAttribute('role','img');chart.setAttribute('aria-label',days.map(d=>`${d.label}: ${d.value} ${unit}`).join('; '));const axis=makeElement('div','chart-axis');[max,Math.round(max*.66),Math.round(max*.33),0].forEach(v=>axis.append(makeElement('span','',v)));const plot=makeElement('div','chart-columns');plot.style.height=`${maxHeight+34}px`;days.forEach((day,i)=>{const column=makeElement('div','activity-column');const bar=makeElement('div',`activity-bar${i===days.length-1?' highlighted':''}`);bar.style.height=`${Math.max(4,day.value/max*maxHeight)}px`;bar.title=`${day.value} ${unit}`;const value=makeElement('span','bar-tooltip',`${day.value} ${unit}`);bar.append(value);column.append(bar,makeElement('span','bar-label',day.label));plot.append(column);});chart.append(axis,plot);return chart;}
export function lineChart(values,labels){const wrap=makeElement('div','line-chart');const svg=svgElement('svg',{viewBox:'0 0 620 180',role:'img','aria-label':values.map((v,i)=>`${labels[i]}: ${v} минут`).join('; '),preserveAspectRatio:'none'});const max=Math.max(60,...values);[25,65,105,145].forEach(y=>svg.append(svgElement('line',{x1:15,y1:y,x2:605,y2:y,stroke:'#eeeaf4','stroke-width':1})));const points=values.map((v,i)=>[15+i*(590/Math.max(1,values.length-1)),145-v/max*120]);const area=svgElement('polygon',{points:[[15,155],...points,[605,155]].map(p=>p.join(',')).join(' '),fill:'#ede5fa'});const line=svgElement('polyline',{points:points.map(p=>p.join(',')).join(' '),fill:'none',stroke:'#a389c6','stroke-width':3,'stroke-linecap':'round','stroke-linejoin':'round'});svg.append(area,line);points.forEach(([cx,cy],i)=>{const dot=svgElement('circle',{cx,cy,r:4,fill:'#fff',stroke:'#a389c6','stroke-width':2});const title=svgElement('title');title.textContent=`${labels[i]}: ${values[i]} мин`;dot.append(title);svg.append(dot);});const ticks=makeElement('div','line-ticks');const step=Math.max(1,Math.ceil(labels.length/7));labels.forEach((label,i)=>{if(i%step===0||i===labels.length-1)ticks.append(makeElement('span','',label));});wrap.append(svg,ticks);return wrap;}
